CREATE VIEW mart_recommendation_v1 AS WITH scored AS (SELECT mbe.GameKey, mbe.GameTitle, mbe.PlayStatusName, mbe.DifficultyScore, mbe.CompletionHours, mbe.CuratedUserScore, mbe.Genres, mbe.Themes, mbe.Modes, mbe.Perspectives, CASE  WHEN ((mbe.Themes ~~* '%Open World%')) THEN (35) ELSE 0 END AS open_world_score, CASE  WHEN ((mbe.Perspectives ~~* '%Third Person%')) THEN (25) ELSE 0 END AS third_person_score, CASE  WHEN ((mbe.Themes ~~* '%Action%')) THEN (20) ELSE 0 END AS action_score, CASE  WHEN ((mbe.Genres ~~* '%Role-playing (RPG)%')) THEN (20) ELSE 0 END AS rpg_score, CASE  WHEN ((mbe.Genres ~~* '%Shooter%')) THEN (10) ELSE 0 END AS shooter_score FROM mart_backlog_enriched AS mbe)SELECT GameKey, GameTitle, PlayStatusName, DifficultyScore, CompletionHours, CuratedUserScore, Genres, Themes, Modes, Perspectives, open_world_score, third_person_score, action_score, rpg_score, shooter_score, ((((open_world_score + third_person_score) + action_score) + rpg_score) + shooter_score) AS explicit_preference_score FROM scored;
